begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table sharing_source(submission uuid,evidence uuid,item uuid);grant select,insert,update on sharing_source to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99960000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Customer current sharing','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)values('10000000-0000-4000-8000-000000000001','99970000-0000-4000-8000-000000000001','99960000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Source sharing','Synthetic',10,'61000000-0000-4000-8000-000000000001');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
insert into sharing_source(submission)values(internal.create_learning_submission('99970000-0000-4000-8000-000000000001','School source'));
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
do $$declare result uuid;begin result:=internal.release_marking(internal.mark_submission((select submission from sharing_source),6,'Human reviewed',1,0,true),1,true);update sharing_source set evidence=(select evidence_id from app.result_revisions where id=result);end$$;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
update sharing_source set item=(internal.portfolio_command('create',null,jsonb_build_object('sourceModel','numeric','evidenceId',evidence,'title','Selected source','reflection','School reflection'),'customer-current-sharing-create',repeat('a',64),'customer-current-sharing')->>'id')::uuid;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.portfolio_command('review',(select item from sharing_source),'{"expectedRevision":1,"feedback":"Human review","featured":false,"parentVisible":true,"confirmParentApproval":true,"confirmSourceReview":true}','customer-current-sharing-review',repeat('b',64),'customer-current-sharing')is not null as reviewed;
select internal.portfolio_command('revoke',(select item from sharing_source),'{"reason":"School revoked current family sharing"}','customer-current-sharing-revoke',repeat('c',64),'customer-current-sharing')is not null as revoked;
select is((select item->>'parentVisible'from jsonb_array_elements(internal.read_portfolio_page(100,null,'20000000-0000-4000-8000-000000000012',null)->'items')item where item->>'id'=(select item::text from sharing_source)),'false','UX13 staff current sharing flag reflects revoked publication');
reset role;select is((select parent_visible from app.portfolio_reviews where item_id=(select item from sharing_source)),true,'UX13 original immutable approval remains historical evidence');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select ok(not exists(select 1 from jsonb_array_elements(internal.read_portfolio_page(100,null,'20000000-0000-4000-8000-000000000012',null)->'items')item where item->>'id'=(select item::text from sharing_source)),'UX13 current parent access remains revoked');
select*from finish();rollback;
